'37XH+C4W, বালিয়াডাঙ্গী–লাহিড়ীহাট সড়ক, বালিয়াডাঙ্গী, ঠাকুরগাঁও','+8801719422675',null,null,null,null,'baliadangi','unverified',
'Public Maps listing; historical public report mentioned registration expiry in 2022–2023; current status requires confirmation: https://www.google.com/maps/search/?api=1&query=Momi+Hospital+Diagnostic+Center+Baliadangi'),
('mission-general-hospital-ranisankail','Mission General Hospital','hospital',
'Mission General Hospital রাণীশংকৈল এলাকায় অনলাইন ম্যাপ ও প্রকাশ্য ব্যবসায়িক তালিকায় পাওয়া একটি বেসরকারি হাসপাতাল। হাসপাতালের বর্তমান বিভাগ, চিকিৎসক, রোগী ভর্তি, পরীক্ষা-নিরীক্ষা এবং জরুরি সেবার প্রাপ্যতা সরাসরি ফোন করে নিশ্চিত করুন। প্রকাশ্য সূত্রে নির্ভুল রাস্তার ঠিকানা পাওয়া যায়নি, তাই যাওয়ার আগে ফোনে সঠিক অবস্থান জেনে নেওয়া প্রয়োজন।',
'রাণীশংকৈল, ঠাকুরগাঁও','+8801777239335',null,null,null,null,'ranisankail','unverified',
'Public business/map listing: https://www.google.com/maps/search/?api=1&query=Mission+General+Hospital+Ranisankail+Thakurgaon')
)
insert into public.hospitals (
  slug, name, category, description, address, phone, email, website,
  latitude, longitude, image, verification, source,
  division_id, district_id, upazila_id, status, last_checked_at, created_at, updated_at
)
select
  r.slug, r.name, r.category, r.description, r.address, r.phone, r.email, r.website,
  r.latitude, r.longitude,
  '/images/hospitals/diagnostic-centre.svg',
  r.verification, r.source,
  d.id, dt.id, u.id,
  'published', now(), now(), now()
from rows r
join public.divisions d on d.slug = 'rangpur'
join public.districts dt on dt.slug = 'thakurgaon' and dt.division_id = d.id
join public.upazilas u on u.slug = r.upazila_slug and u.district_id = dt.id
on conflict (slug) do update set
  name = excluded.name,
  category = excluded.category,
  description = excluded.description,
  address = excluded.address,
  phone = coalesce(excluded.phone, public.hospitals.phone),
  email = coalesce(excluded.email, public.hospitals.email),
  website = coalesce(excluded.website, public.hospitals.website),
  latitude = coalesce(excluded.latitude, public.hospitals.latitude),
  longitude = coalesce(excluded.longitude, public.hospitals.longitude),
  verification = excluded.verification,
  source = excluded.source,
  division_id = excluded.division_id,
  district_id = excluded.district_id,
  upazila_id = excluded.upazila_id,
  status = 'published',
  last_checked_at = now(),
  updated_at = now();

commit;

-- Verification: expected records inserted/updated by this script.
select category, verification, count(*) as total
from public.hospitals
where district_id = (select id from public.districts where slug = 'thakurgaon')
group by category, verification
order by category, verification;
